    l_branch_id         NUMBER;
    l_table_name        VARCHAR2(100);
    l_row_id            NUMBER;
    l_doc_category_id   NUMBER;
    l_status_id         NUMBER;
    l_expires_date      TIMESTAMP;
    l_created_date      DATE;
    l_category_name_ar  VARCHAR2(250);
    l_category_name_en  VARCHAR2(250);
    -- متغيرات مساعدة للتواريخ
    l_issue_date_str    VARCHAR2(20);
    l_expiry_date_str   VARCHAR2(20);
BEGIN
    -- ============================================================
    -- 1) قراءة الباراميتر
    -- ============================================================
    l_token := :token;

    IF l_token IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''رمز الجلسة مطلوب'',       p_write' || '_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Session token required'',   p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',            p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    -- ============================================================
    -- 2) البحث عن الـ session
