    BEGIN
        SELECT s.ID, s.COMPANY_ID, s.BRANCH_ID, s.TABLE_NAME, s.ROW_ID,
               s.DOCUMENT_CATEGORY_ID, s.STATUS_ID, s.EXPIRES_DATE, s.CREATED_DATE,
               s.SHORT_CODE
        INTO   l_session_id, l_company_id, l_branch_id, l_table_name, l_row_id,
               l_doc_category_id, l_status_id, l_expires_date, l_created_date,
               l_short_code
        FROM   GNL_ATTACHMENT_SESSION s
        WHERE  (s.SESSION_TOKEN = l_token OR s.SHORT_CODE = l_token)
