    IF l_doc_category_id IS NOT NULL THEN
        BEGIN
            SELECT NAME, ARABIC_NAME
            INTO   l_category_name_en, l_category_name_ar
            FROM   GNL_DOCUMENT_CATEGORIES
            WHERE  ID = l_doc_category_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;
    END IF;

    -- ============================================================
    -- 5) تحديث حالة الجلسة لـ 2
    -- ============================================================
    UPDATE GNL_ATTACHMENT_SESSION
    SET    STATUS_ID     = 2,
           UPLOADED_DATE = SYSTIMESTAMP
    WHER' || 'E  ID = l_session_id;
