    -- ===== كائن الـ session =====
    APEX_JSON.open_object(''session'');
        APEX_JSON.write(''id'',                 l_session_id,        p_write_null => TRUE);
        APEX_JSON.write(''shortCode'',          l_short_code,        p_write_null => TRUE);
        APEX_JSON.write(''companyId'',          l_company_id,        p_write_null => TRUE);
