        APEX_JSON.write(''rowId'',              l_row_id,            p_write_null => TRUE);
        APEX_JSON.write(''documentCategoryId'', l_doc_category_id,   p_write_null => TRUE);
        APEX_JSON.write(''categoryNameAr'',     l_category_name_ar,  p_write_null => TRUE);
        APEX_JSON.write(''categoryNameEn'',     l_category_name_en,  p_write_null => TRUE);
        APEX_JSON.write(''expiresDate'',        TO_CHAR(l_expires_date, ''YYYY-MM-DD"T"HH24:MI:SS''), p_write_null => TRUE);
    APEX_JSON.close_object;

    -- ============================================================
