    APEX_JSON.open_array(''attachments'');

    -- --- المرفقات المرفوعة (متوقعة + رفع حر) ---
    FOR rec IN (
        SELECT att.ID                    AS ATTACHMENT_ID,
               att.CODE                  AS ATTACHMENT_CODE,
               att.' || 'FILE_NAME,
               att.MIME_TYPE,
               att.FILE_PATH,
               att.FILE_SIZE,
               att.DESCRIPTION           AS FILE_DESCRIPTION,
               att.DOCUMENT_TYPE_ID,
               att.DOCUMENT_CATEGORIE_ID AS DOCUMENT_CATEGORY_ID,
               att.ISSUE_DATE,
               att.EXPIRY_DATE,
               att.CREATED,
               att.CREATED_BY,
               dt.ARABIC_NAME            AS DOC_NAME_AR,
               dt.NAME                   AS DOC_NAME_EN,
               dt.IS_MANDATORY,
               dt.HAS_EXPIRY,
               dt.IS_RENEWABLE,
