               cat.ARABIC_NAME           AS CAT_NAME_AR,
               cat.NAME                  AS CAT_NAME_EN
        FROM   GNL_ATTACHMENT_SYSTEM att
        LEFT JOIN GNL_DOCUMENT_TYPES      dt  ON dt.ID  = att.DOCUMENT_TYPE_ID
        LEFT JOIN GNL_DOCUMENT_CATEGORIES' || ' cat ON cat.ID = att.DOCUMENT_CATEGORIE_ID
        WHERE  att.TABLE_NAME = l_table_name
        AND    att.ROW_ID     = l_row_id
        AND    att.STATUS     = ''1''
        AND    (l_doc_category_id IS NULL
                OR att.DOCUMENT_CATEGORIE_ID = l_doc_category_id)
        ORDER BY CASE WHEN att.DOCUMENT_TYPE_ID IS NOT NULL THEN 0 ELSE 1 END,
                 att.CREATED DESC
    ) LOOP
        -- تجهيز التواريخ في متغيرات مساعدة
        IF rec.ISSUE_DATE IS NULL THEN
            l_issue_date_str := NULL;
        ELSE
            l_issue_date_str := TO_CHAR(rec.ISSUE_DATE, ''DD-MM-YYYY'');
        END IF;

        IF rec.EXPIRY_DATE IS NULL THEN
            l_expiry_date_str := NULL;
        ELSE
            l_expiry_date_str := TO_CHAR(rec.EXPIRY_DATE, ''DD-MM-YYYY'');
        END IF;

        APEX_JSON.open_object;
            -- معرّفات
            APEX_JSON.write(''attachmentId'',         rec.ATTACHMENT_ID,            p_write_null => TRUE);
            APE' || 'X_JSON.write(''attachmentCode'',       rec.ATTACHMENT_CODE,          p_write_null => TRUE);
            APEX_JSON.write(''documentTypeId'',       rec.DOCUMENT_TYPE_ID,         p_write_null => TRUE);
