            APEX_JSON.write(''categoryNameAr'',       rec.CAT_NAME_AR,              p_write_null => TRUE);
            APEX_JSON.write(''categoryNameEn'',       rec.CAT_NAME_EN,              p_write_null => TRUE);
            -- بيانات الملف
            APEX_JSON.write(''fileName'',             rec.FILE_NAME,                p_write_null => TRUE);
            APEX_JSON.write(''mimeType'',             rec.MIME_TYPE,                p_write_null => TRU' || 'E);
            APEX_JSON.write(''filePath'',             rec.FILE_PATH,                p_write_null => TRUE);
            APEX_JSON.write(''fileSize'',             NVL(rec.FILE_SIZE, 0),        p_write_null => TRUE);
            APEX_JSON.write(''description'',          rec.FILE_DESCRIPTION,         p_write_null => TRUE);
            -- إعدادات الإلزام
            APEX_JSON.write(''isMandatory'',          CASE WHEN rec.IS_MANDATORY = ''Y'' THEN TRUE ELSE FALSE END);
            APEX_JSON.write(''hasExpiry'',            CASE WHEN rec.HAS_EXPIRY   = ''Y'' THEN TRUE ELSE FALSE END);
            APEX_JSON.write(''isRenewable'',          CASE WHEN rec.IS_RENEWABLE = ''Y'' THEN TRUE ELSE FALSE END);
            APEX_JSON.write(''allowMultiple'',        CASE WHEN rec.ALLOW_MULTIPLE = ''Y'' THEN TRUE ELSE FALSE END);
            APEX_JSON.write(''maxFileSizeMb'',        NVL(rec.MAX_FILE_SIZE_MB, 0), p_write_null => TRUE);
            APEX_JSON.write(''expiryAlertDays'',      NVL(rec.EXPIRY_ALERT_DAYS, 0), p_' || 'write_null => TRUE);
            -- التواريخ
            APEX_JSON.write(''issueDate'',            l_issue_date_str,             p_write_null => TRUE);
            APEX_JSON.write(''expiryDate'',           l_expiry_date_str,            p_write_null => TRUE);
            APEX_JSON.write(''isExpired'',
                CASE WHEN rec.EXPIRY_DATE IS NOT NULL
                      AND rec.EXPIRY_DATE < TRUNC(SYSDATE)
                     THEN TRUE ELSE FALSE END);
            APEX_JSON.write(''uploadedAt'',           TO_CHAR(rec.CREATED, ''DD-MM-YYYY HH24:MI''), p_write_null => TRUE);
            APEX_JSON.write(''uploadedBy'',           rec.CREATED_BY,               p_write_null => TRUE);
            -- الحالة والنوع
