                p_write_null => TRUE);
            -- الأزرار للموبايل
            APEX_JSON.write(''isShowButtonUpload'',   FALSE);
            APEX_JSON.write(''isShowButtonView'',     TRUE);
            APEX_JSON.write(''isShowButtonDelete'',   TRUE);
        APEX_JSON.close_object;
    END LOOP;

    -- --- المرفقات المطلوبة لكن لسه مش مرفوعة ---
    IF l_doc_category_id IS NOT NULL THEN
        FOR rec IN (
            SELECT dt.ID                AS DOCUMENT_TYPE_ID,
                   dt.CODE,
                   dt.NAME              AS DOC_NAME_EN,
                   dt.ARABIC_NAME       AS DOC_NAME_AR,
                   dt.DESCRIPTION,
