                   cat.ARABIC_NAME ' || '     AS CAT_NAME_AR,
                   cat.NAME             AS CAT_NAME_EN
            FROM   GNL_DOCUMENT_TYPES dt
            LEFT JOIN GNL_DOCUMENT_CATEGORIES cat ON cat.ID = dt.CATEGORY_ID
            WHERE  dt.CATEGORY_ID = l_doc_category_id
            AND    dt.STATUS = ''1''
