                SELECT DOCUMENT_TYPE_ID
                FROM   GNL_ATTACHMENT_SYSTEM
                WHERE  TABLE_NAME = l_table_name
                AND    ROW_ID     = l_row_id
                AND    STATUS     = ''1''
                AND    DOCUMENT_TYPE_ID IS NOT NULL
            )
            ORDER BY CASE WHEN rec.IS_MANDATORY = ''Y'' THEN 0 ELSE 1 END,
                     dt.DISPLAY_ORDER, dt.ID
        ) LOOP
            APEX_JSON.open_object;
                -- معرّفات
                APEX_JSON.write(''attachmentId'',         l_session_id * 0,             p_write_null => TRUE);  -- placeholder NUMBER
                APEX_JSON.write(''attachmentCode'',  ' || '     '''',                           p_write_null => TRUE);
                APEX_JSON.write(''documentTypeId'',       rec.DOCUMENT_TYPE_ID,         p_write_null => TRUE);
