                APEX_JSON.write(''categoryNameAr'',       rec.CAT_NAME_AR,              p_write_null => TRUE);
                APEX_JSON.write(''categoryNameEn'',       rec.CAT_NAME_EN,              p_write_null => TRUE);
                -- بيانات الملف (فارغة)
                APEX_JSON.write(''fileName'',             '''',                           p_write_null => TRUE);
                APEX_JSON.write(''mimeType'',             '''',                           p_w' || 'rite_null => TRUE);
                APEX_JSON.write(''filePath'',             '''',                           p_write_null => TRUE);
                APEX_JSON.write(''fileSize'',             0,                            p_write_null => TRUE);
