                APEX_JSON.write(''isRenewable'',          CASE WHEN rec.IS_RENEWABLE = ''Y'' THEN TRUE ELSE FALSE END);
                APEX_JSON.write(''allowMultiple'',        CASE WHEN rec.ALLOW_MULTIPLE = ''Y'' THEN TRUE ELSE FALSE END);
                APEX_JSON.write(''maxFileSizeMb'',        NVL(rec.MAX_FILE_SIZE_MB, 0), p_write_null => TRUE);
                APEX_JSON.write(''' || 'expiryAlertDays'',      NVL(rec.EXPIRY_ALERT_DAYS, 0), p_write_null => TRUE);
                -- التواريخ (فارغة)
                APEX_JSON.write(''issueDate'',            '''',                           p_write_null => TRUE);
