                APEX_JSON.write(''uploadedAt'',           '''',                           p_write_null => TRUE);
                APEX_JSON.write(''uploadedBy'',           '''',                           p_write_null => TRUE);
                -- الحالة والنوع
                APEX_JSON.write(''uploadStatus'',         ''MISSING'',                    p_write_null => TRUE);
                APEX_JSON.write(''sourceType'',           ''SYSTEM'',                     p_write_null => TRUE);
                -- الأزرار للموبايل
                APEX_JSON.write(''isShowButtonUpload'',   TRUE);
                APEX_JSON' || '.write(''isShowButtonView'',     FALSE);
                APEX_JSON.write(''isShowButtonDelete'',   FALSE);
            APEX_JSON.close_object;
        END LOOP;
    END IF;

    APEX_JSON.close_array;

