'-- ============================================================
-- GET /api/v1/hr/leave-types
-- Module  : api/v1
-- Template: hr/leave-types
-- Method  : GET
-- Auth    : Token Required
-- Query   : ?leaveTypeId=3 (اختياري - لو NULL يجيب الكل)
-- ============================================================
DECLARE
    l_header_value    VARCHAR2(4000);
    l_bearer_token    VARCHAR2(4000);
    l_token           APEX_JWT.T_TOKEN;
    l_user_object     APEX_JSON.T_VALUES;
    l_user_id         NUMBER;
    l_iss             VARCHAR2(200);
    l_total           NUMBER := 0;
    l_leave_type_id   NUMBER;

BEGIN
    -- ===== 1. TOKEN VALIDATION =====
    l_header_value := OWA_UTIL.get_cgi_env(''Authorization'');

    IF l_header_value IS NULL OR INSTR(l_header_value, ''Bearer '') != 1 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''يرجى تسجيل الدخول أولاً'', p_w' || 'rite_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Authentication required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''TOKEN_REQUIRED'',         p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 401;
        RETURN;
    END IF;

    l_bearer_token := SUBSTR(l_header_value, 8);

    BEGIN
        l_token := APEX_JWT.DECODE(
            p_value         => l_bearer_token,
            p_signature_key => SYS.UTL_RAW.CAST_TO_RAW(''secretKey'')
          );
          APEX_JSON.PARSE(l_user_object, l_token.payload);

          IF NOT APEX_JSON.DOES_EXIST(p_path => ''sub'', p_values => l_user_object) THEN
              APEX_JSON.open_object;
              APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
              APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
              APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
              APEX_JSON.write(''errorCode'', ''INVALID_TOKE' || 'N'',  p_write_null => TRUE);
              APEX_JSON.close_object;
              :status := 401;
              RETURN;
          END IF;

          l_iss := APEX_JSON.GET_VARCHAR2(p_path => ''iss'', p_values => l_user_object);

          IF l_iss IS NULL OR l_iss != ''ORDS'' THEN
              APEX_JSON.open_object;
              APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
              APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
              APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
              APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
              APEX_JSON.close_object;
              :status := 401;
              RETURN;
          END IF;

          l_user_id := TO_NUMBER(APEX_JSON.GET_VARCHAR2(p_path => ''sub'', p_values => l_user_object));

      EXCEPTION
          WHEN OTHERS THEN
              APEX_JSON.open_object;
              APEX_JSON.write(''status'',    ''error'',          p_write_null =' || '> TRUE);
              APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
              APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
              APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
              APEX_JSON.close_object;
              :status := 401;
              RETURN;
      END;

      -- ===== 2. GET QUERY PARAMS =====
      l_leave_type_id := TO_NUMBER(:leave_type_id);  -- لو NULL → يجيب الكل

      -- ===== 3. GET TOTAL =====
      SELECT COUNT(*) INTO l_total
      FROM   HR_LEAVE_TYPES
      WHERE  IS_MOBILE_APP = 1
      AND    (l_leave_type_id IS NULL OR ID = l_leave_type_id);

      -- ===== 4. SUCCESS RESPONSE =====
      :status := 200;
      APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''success'',                    p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''تم جلب أنواع الإجازات بنجاح'', p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''Leave types retrieved succ' || 'essfully'', p_write_null => TRUE);
          APEX_JSON.write(''total'',     l_total,                      p_write_null => TRUE);

          APEX_JSON.open_array(''leaveTypes'');

          FOR rec IN (
              SELECT ID, NAME, ARABIC_NAME
              FROM   HR_LEAVE_TYPES
              WHERE  IS_MOBILE_APP = 1
              AND    (l_leave_type_id IS NULL OR ID = l_leave_type_id)
              ORDER BY ID
          ) LOOP
              APEX_JSON.open_object;
                  APEX_JSON.write(''id'',     rec.ID,          p_write_null => TRUE);
                  APEX_JSON.write(''nameEn'', rec.NAME,        p_write_null => TRUE);
                  APEX_JSON.write(''nameAr'', rec.ARABIC_NAME, p_write_null => TRUE);
              APEX_JSON.close_object;
          END LOOP;

          APEX_JSON.close_array;
      APEX_JSON.close_object;

  EXCEPTION
      WHEN OTHERS THEN
          APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''error'',                        p_write_null => TRUE);
          APEX_' || 'JSON.write(''messageAr'', ''حدث خطأ في النظام'',            p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''An unexpected error occurred'', p_write_null => TRUE);
          APEX_JSON.write(''errorCode'', ''SYSTEM_ERROR'',                 p_write_null => TRUE);
          APEX_JSON.close_object;
          :status := 500;
  END;');

  ORDS.DEFINE_MODULE(
      p_module_name    => 'MyEmployees',
      p_base_path      => '/MyEmployees/',
      p_items_per_page => 25,
      p_status         => 'PUBLISHED',
      p_comments       => NULL);

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'MyEmployees',
      p_pattern        => 'Workpermits',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => NULL);

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'MyEmployees',
      p_pattern        => 'Workpermits',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'-- ============================================================
-- POST /api/v1/hr/work-permits
-- Module  : api/v1
-- Template: hr/work-permits
-- Method  : POST
-- Auth    : Token Required
-- Body    : employeeId, permitDate, permitType, durationMinutes, notes
-- ============================================================
DECLARE
    l_header_value      VARCHAR2(4000);
    l_bearer_token      VARCHAR2(4000);
    l_token             APEX_JWT.T_TOKEN;
    l_user_object       APEX_JSON.T_VALUES;
    l_user_id           NUMBER;
    l_user_type         VARCHAR2(200);
    l_iss               VARCHAR2(200);

    l_body              CLOB;
    l_body_values       APEX_JSON.T_VALUES;

    l_username          VARCHAR2(200);
    l_company_id        NUMBER;
    l_branch_id         NUMBER;

    -- Body Variables
    l_employee_id       NUMBER;
    l_permit_date       DATE;
    l_permit_type       VARCHAR2(20);
    l_duration_minutes  NUMBER;
    l_notes             VA' || 'RCHAR2(4000);

    -- Work Variables
    l_new_id            NUMBER;
    l_emp_check         NUMBER := 0;
    l_dup_check         NUMBER := 0;

BEGIN
    -- ===== 1. TOKEN VALIDATION =====
    l_header_value := OWA_UTIL.get_cgi_env(''Authorization'');

    IF l_header_value IS NULL OR INSTR(l_header_value, ''Bearer '') != 1 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''يرجى تسجيل الدخول أولاً'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Authentication required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''TOKEN_REQUIRED'',         p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 401;
        RETURN;
    END IF;

    l_bearer_token := SUBSTR(l_header_value, 8);

    BEGIN
        l_token := APEX_JWT.DECODE(
            p_value         => l_bearer_token,
            p_signature_key => SYS.UTL_RA' || 'W.CAST_TO_RAW(''secretKey'')
        );
        APEX_JSON.PARSE(l_user_object, l_token.payload);

        IF NOT APEX_JSON.DOES_EXIST(p_path => ''sub'', p_values => l_user_object) THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_iss := APEX_JSON.GET_VARCHAR2(p_path => ''iss'', p_values => l_user_object);

        IF l_iss IS NULL OR l_iss != ''ORDS'' THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_user_id   := TO_NUMBER(APEX_JSON.GET_VARCHAR2(p_path => ''sub'', p_values => l_user_object));
        l_user_type :=           APEX_JSON.GET_VARCHAR2(p_path => ''aud'', p_values => l_user_object);

    EXCEPTION
        WHEN OTHERS THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
    END;

    -- ===== 2. GET USER INFO =====
    BEGIN
        SELECT U.USERNAME, U.DEFAULT_COMPANY_ID, U.DEFAULT_BRANCH_ID
        INTO   l_username, l_company_id, l_branch_id
        FROM   SEC_USERS U
        WHERE  U.ID = l_user_id
        AND    ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',               p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''المستخدم غير موجود'',   p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''User not found'',      p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''USER_NOT_FOUND'',       p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 404;
            RETURN;
      END;

      -- ===== 3. READ BODY =====
      l_body := :body_text;

      IF l_body IS NULL THEN
          APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''error'',                      p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''لم نتمكن من قراءة البيانات'', p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''Request body is empty'',      p_write_null => TRUE);
          APEX_JSON.write(''errorCode'', ''INVALID_REQUEST'',            p_write_null => TRUE);
          APEX_JSON.close_object;
          :status := 400;
          RETURN;
      END IF;

      APEX_JSON.PARSE(l_body_values, l_body);

      -- ===== 4. EXTRACT PARAMS =====
      l_employee_id      := APEX_JSON.GET_NUMBER(p_path => ''employeeId'', p_values => l_body_values);
      l_permit_date      := TO_DATE(TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''permitDate'',      p_values => l_body_values)), ''DD/MM/YYYY'');
      l_permit_type      := UPPER(TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''permitType'',      p_values => l_body_values)));
      l_duration_minutes := APEX_JSON.GET_NUMBER(p_path => ''durationMinutes'', p_values => l_body_values);
      l_notes            := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''notes'', p_values => l_body_values));

      -- ===== 5. VALIDATE REQUIRED =====
      IF l_employee_id IS NULL THEN
          APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''رقم الموظف مطلوب'',        p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''employeeId is required'', p_write_null => TRUE);
          APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',           p_write_null => TRUE);
          APEX_JSON.close_object;
          :status := 400;
          RETURN;
      END IF;

      IF l_permit_date IS NULL THEN
          APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''تاريخ التصريح مطلوب'',    p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''permitDate is required'', p_write_null => TRUE);
          APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',           p_write_null => TRUE);
          APEX_JSON.close_object;
          :status := 400;
          RETURN;
      END IF;

      IF l_permit_type IS NULL THEN
          APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''نوع التصريح مطلوب'',       p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''permitType is required'', p_write_null => TRUE);
          APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',           p_write_null => TRUE);
          APEX_JSON.close_object;
          :status := 400;
          RETURN;
      END IF;

      IF l_permit_type NOT IN (''PERMISSION'', ''RECALL'') THEN
          APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''error'',                                        p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''نوع التصريح يجب أن يكون PERMISSION أو RECALL'', p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''permitType must be PERMISSION or RECALL'',      p_write_null => TRUE);
          APEX_JSON.write(''errorCode'', ''INVALID_DATA'',                                 p_write_null => TRUE);
          APEX_JSON.close_object;
          :status := 400;
          RETURN;
      END IF;

      -- لو PERMISSION → durationMinutes مطلوب
      IF l_permit_type = ''PERMISSION'' AND (l_duration_minutes IS NULL OR l_duration_minutes <= 0) THEN
          APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''error'',                                           p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''مدة الاستئذان مطلوبة ويجب أن تكون أكبر من صفر'',  p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''durationMinutes is required for PERMISSION type'', p_write_null => TRUE);
          APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',                                   p_write_null => TRUE);
          APEX_JSON.close_object;
          :status := 400;
          RETURN;
      END IF;

      -- ===== 6. CHECK EMPLOYEE EXISTS =====
      SELECT COUNT(*) INTO l_emp_check
      FROM   HR_EMPLOYEES
      WHERE  EMPLOYEE_ID = l_employee_id;

      IF l_emp_check = 0 THEN
          APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''error'',               p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''الموظف غير موجود'',    p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''Employee not found'',  p_write_null => TRUE);
          APEX_JSON.write(''errorCode'', ''EMPLOYEE_NOT_FOUND'',  p_write_null => TRUE);
          APEX_JSON.close_object;
          :status := 404;
          RETURN;
      END IF;

      -- ===== 7. CHECK DUPLICATE =====
      SELECT COUNT(*) INTO l_dup_check
      FROM   HR_WORK_PERMITS
      WHERE  EMPLOYEE_ID        = l_employee_id
      AND    TRUNC(PERMIT_DATE) = TRUNC(l_permit_date)
      AND    PERMIT_TYPE        = l_permit_type
      AND    STATUS             = ''1'';

      IF l_dup_check > 0 THEN
          APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''error'',                                                p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''يوجد تصريح مسجل بالفعل لهذا الموظف في هذا اليوم'',     p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''A work permit already exists for this employee today'', p_write_null => TRUE);
          APEX_JSON.write(''errorCode'', ''DUPLICATE_PERMIT'',                                     p_write_null => TRUE);
          APEX_JSON.close_object;
          :status := 409;
          RETURN;
      END IF;

      -- ===== 8. INSERT =====
      INSERT INTO HR_WORK_PERMITS (
          COMPANY_ID,
          BRANCH_ID,
          EMPLOYEE_ID,
          PERMIT_DATE,
          PERMIT_TYPE,
          DURATION_MINUTES,
          NOTES,
          STATUS,
          CREATED_BY,
          CREATED_BY_USER_ID,
          CREATED_DATE
      ) VALUES (
          l_company_id,
          l_branch_id,
          l_employee_id,
          l_permit_date,
          l_permit_type,
          CASE WHEN l_permit_type = ''PERMISSION'' THEN l_duration_minutes ELSE NULL END,
          l_notes,
          ''1'',
          l_username,
          l_user_id,
          SYSDATE
      ) RETURNING ID INTO l_new_id;

      COMMIT;

      -- ===== 9. SUCCESS RESPONSE =====
      :status := 201;
      APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''success'',                       p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''تم إضافة التصريح بنجاح'',        p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''Work permit added successfully'', p_write_null => TRUE);
          APEX_JSON.open_object(''workPermit'');
              APEX_JSON.write(''id'',              l_new_id,                             p_write_null => TRUE);
              APEX_JSON.write(''employeeId'',      l_employee_id,                        p_write_null => TRUE);
              APEX_JSON.write(''permitDate'',      TO_CHAR(l_permit_date, ''DD/MM/YYYY''), p_write_null => TRUE);
              APEX_JSON.write(''permitType'',      l_permit_type,                        p_write_null => TRUE);
              APEX_JSON.write(''durationMinutes'', l_duration_minutes,                   p_write_null => TRUE);
              APEX_JSON.write(''notes'',           l_notes,                              p_write_null => TRUE);
              APEX_JSON.write(''status'',          ''1'',                                  p_write_null => TRUE);
          APEX_JSON.close_object;
      APEX_JSON.close_object;

  EXCEPTION
      WHEN OTHERS THEN
          ROLLBACK;
          APEX_JSON.open_object;
          APEX_JSON.write(''status'',    ''error'',                        p_write_null => TRUE);
          APEX_JSON.write(''messageAr'', ''حدث خطأ في النظام'',            p_write_null => TRUE);
          APEX_JSON.write(''messageEn'', ''An unexpected error occurred'', p_write_null => TRUE);
          APEX_JSON.write(''errorCode'', ''SYSTEM_ERROR'',                 p_write_null => TRUE);
          APEX_JSON.close_object;
          :status := 500;
  END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'MyEmployees',
      p_pattern        => 'Present',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => NULL);
ORDS.DEFINE_HANDLER(
      p_module_name    => 'MyEmployees',
      p_pattern        => 'Present',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'DECLARE
    l_header_value    VARCHAR2(4000);
    l_bearer_token    VARCHAR2(4000);
    l_token           APEX_JWT.T_TOKEN;
    l_user_object     APEX_JSON.T_VALUES;
    l_user_id         NUMBER;
    l_user_type       VARCHAR2(200);
    l_iss             VARCHAR2(200);

    l_employee_id     NUMBER;
    l_date_filter     DATE;
    l_total           NUMBER := 0;

BEGIN
    -- ===== 1. TOKEN VALIDATION =====
    l_header_value := OWA_UTIL.get_cgi_env(''Authorization'');

    IF l_header_value IS NULL OR INSTR(l_header_value, ''Bearer '') != 1 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''يرجى تسجيل الدخول أولاً'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Authentication required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''TOKEN_REQUIRED'',         p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := ' || '401;
        RETURN;
    END IF;

    l_bearer_token := SUBSTR(l_header_value, 8);

    BEGIN
        l_token := APEX_JWT.DECODE(
            p_value         => l_bearer_token,
            p_signature_key => SYS.UTL_RAW.CAST_TO_RAW(''secretKey'')
        );
        APEX_JSON.PARSE(l_user_object, l_token.payload);

        IF NOT APEX_JSON.DOES_EXIST(p_path => ''sub'', p_values => l_user_object) THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_iss := APEX_JSON.GET_VARCHAR2(p_path => ''iss'', p_values => l_user_object);

        IF l_iss IS NULL ' || 'OR l_iss != ''ORDS'' THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_user_id   := TO_NUMBER(APEX_JSON.GET_VARCHAR2(p_path => ''sub'', p_values => l_user_object));
        l_user_type :=           APEX_JSON.GET_VARCHAR2(p_path => ''aud'', p_values => l_user_object);

    EXCEPTION
        WHEN OTHERS THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid t' || 'oken'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
    END;

    -- ===== 2. GET EMPLOYEE_ID (المدير) =====
    BEGIN
        SELECT E.EMPLOYEE_ID
        INTO   l_employee_id
        FROM   SEC_USERS U
        JOIN   HR_EMPLOYEES E
            ON U.USER_TYPE    = ''EMPLOYEE''
            AND E.EMPLOYEE_ID = U.REFERENCE_USER_ID
        WHERE  U.ID = l_user_id
        AND    ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',                          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''المستخدم غير مرتبط بموظف'',       p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''User is not linked to employee'', p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''EMPLOYEE_NOT_LINKED'',      ' || '      p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 400;
            RETURN;
    END;

    -- ===== 3. READ QUERY PARAMS =====
    l_date_filter := NVL(
        TO_DATE(:date_filter, ''DD-MM-YYYY''),
        TRUNC(SYSDATE)
    );

    -- ===== 4. GET TOTAL COUNT =====
    SELECT COUNT(*) INTO l_total
    FROM HR_EMPLOYEES E
    JOIN (
        SELECT D.ID AS DEPT_ID
        FROM   HR_DEPARTMENT D
        START WITH D.MANAGER_ID = l_employee_id
        CONNECT BY PRIOR D.ID   = D.PARENT_ID
    ) DEPT_HIER ON DEPT_HIER.DEPT_ID = E.DEPARTMENT_ID
    WHERE E.STATUS = 1; -- الفلترة بحالة الموظف (تم إلغاء استثناء المدير)

    -- ===== 5. SUCCESS RESPONSE =====
    :status := 200;
    APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''success'',                     p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''تم جلب بيانات الحضور بنجاح'',  p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Attendanc' || 'e retrieved successfully'', p_write_null => TRUE);
        APEX_JSON.write(''date'',      TO_CHAR(l_date_filter, ''DD/MM/YYYY''), p_write_null => TRUE);
        APEX_JSON.write(''total'',     l_total,                        p_write_null => TRUE);

        APEX_JSON.open_array(''attendance'');

        FOR rec IN (
            SELECT
                E.EMPLOYEE_ID,
                E.CODE                  AS EMPLOYEE_CODE,
                E.FULL_NAME_AR,
                E.FULL_NAME_EN,
                DEPT_HIER.DEPT_NAME     AS DEPARTMENT_NAME,

                TO_CHAR(A.CHECK_IN_TIME,  ''HH12:MI PM'')  AS CHECK_IN_TIME,
                CASE WHEN A.HAS_OUT = 1
                     THEN TO_CHAR(A.CHECK_OUT_TIME, ''HH12:MI PM'')
                END                                       AS CHECK_OUT_TIME,
                CASE WHEN A.HAS_OUT = 1
                     THEN ROUND((A.CHECK_OUT_TIME - A.CHECK_IN_TIME) * 24, 2)
                END                                       AS WOR' || 'KING_HOURS,

                -- ===== ATTENDANCE STATUS =====
                CASE
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND CTO.EMPLOYEE_ID IS NOT NULL 
                        THEN ''COMPLETE_CTO''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND OT.EMPLOYEE_ID IS NOT NULL 
                        THEN ''COMPLETE_OVERTIME''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''PERMISSION''
                        THEN ''COMPLETE_PERMISSION''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''RECALL''
                        THEN ''COMPLETE_RECALL''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 
                        THEN ''COMPLETE''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 AND CTO.EMPLOYEE_ID IS NOT NULL 
                        THEN ''NO_CHECKOUT_CTO''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT' || ',0) = 0 AND OT.EMPLOYEE_ID IS NOT NULL 
                        THEN ''NO_CHECKOUT_OVERTIME''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''PERMISSION''
                        THEN ''NO_CHECKOUT_PERMISSION''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''RECALL''
                        THEN ''NO_CHECKOUT_RECALL''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 
                        THEN ''NO_CHECKOUT''
                    WHEN LV.EMPLOYEE_ID IS NOT NULL 
                        THEN ''LEAVE''
                    WHEN MS.EMPLOYEE_ID IS NOT NULL 
                        THEN ''MISSION''
                    WHEN WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''PERMISSION''
                        THEN ''ABSENT_PERMISSION''
                    WHEN WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''RECALL''
                        THEN ''A' || 'BSENT_RECALL''
                    WHEN AB.EMPLOYEE_ID IS NOT NULL 
                        THEN ''ABSENT''
                    WHEN PH.EMPLOYEE_ID IS NOT NULL 
                        THEN ''PUBLIC_HOLIDAY''
                    WHEN CD.EMPLOYEE_ID IS NOT NULL 
                        THEN ''COMPENSATORY''
                    WHEN WO.EMPLOYEE_ID IS NOT NULL 
                        THEN ''WEEKLY_OFF''
                    ELSE ''NOT_PRESENT''
                END AS ATTENDANCE_STATUS,

                -- ===== STATUS AR =====
                CASE
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND CTO.EMPLOYEE_ID IS NOT NULL 
                        THEN ''حاضر - مكتمل (بدل يعوض)''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND OT.EMPLOYEE_ID IS NOT NULL 
                        THEN ''حاضر - مكتمل (إضافي أجر)''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''PERMISSION''
                        THEN ''حا' || 'ضر - مكتمل (استئذان)''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''RECALL''
                        THEN ''حاضر - مكتمل (استدعاء)''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 
                        THEN ''حاضر - مكتمل''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 AND CTO.EMPLOYEE_ID IS NOT NULL 
                        THEN ''حاضر - بدل يعوض''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 AND OT.EMPLOYEE_ID IS NOT NULL 
                        THEN ''حاضر - إضافي أجر''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''PERMISSION''
                        THEN ''حاضر - استئذان''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''RECALL''
                        THEN ''حاضر - استدعاء''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 ' || '
                        THEN ''حاضر - لم ينصرف''
                    WHEN LV.EMPLOYEE_ID IS NOT NULL 
                        THEN ''إجازة - '' || LV.LEAVE_TYPE_AR
                    WHEN MS.EMPLOYEE_ID IS NOT NULL 
                        THEN ''مهمة عمل''
                    WHEN WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''PERMISSION''
                        THEN ''غياب - استئذان''
                    WHEN WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''RECALL''
                        THEN ''غياب - استدعاء''
                    WHEN AB.EMPLOYEE_ID IS NOT NULL 
                        THEN ''غياب مسجل''
                    WHEN PH.EMPLOYEE_ID IS NOT NULL 
                        THEN ''عطلة رسمية''
                    WHEN CD.EMPLOYEE_ID IS NOT NULL 
                        THEN ''راحة مستحقة''
                    WHEN WO.EMPLOYEE_ID IS NOT NULL 
                        THEN ''راحة أسبوعية''
                    ELSE ''لم يحضر''
                END AS STATUS_AR,

             ' || '   -- ===== STATUS EN =====
                CASE
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND CTO.EMPLOYEE_ID IS NOT NULL 
                        THEN ''Present - Complete (CTO)''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND OT.EMPLOYEE_ID IS NOT NULL 
                        THEN ''Present - Complete (Overtime)''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''PERMISSION''
                        THEN ''Present - Complete (Permission)''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''RECALL''
                        THEN ''Present - Complete (Recall)''
                    WHEN A.HAS_IN = 1 AND A.HAS_OUT = 1 
                        THEN ''Present - Complete''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 AND CTO.EMPLOYEE_ID IS NOT NULL 
                        THEN ''Present - CTO''
                    WHEN A.HAS_IN =' || ' 1 AND NVL(A.HAS_OUT,0) = 0 AND OT.EMPLOYEE_ID IS NOT NULL 
                        THEN ''Present - Overtime''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''PERMISSION''
                        THEN ''Present - Permission''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 AND WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''RECALL''
                        THEN ''Present - Recall''
                    WHEN A.HAS_IN = 1 AND NVL(A.HAS_OUT,0) = 0 
                        THEN ''Present - No Check Out''
                    WHEN LV.EMPLOYEE_ID IS NOT NULL 
                        THEN ''Leave - '' || LV.LEAVE_TYPE_EN
                    WHEN MS.EMPLOYEE_ID IS NOT NULL 
                        THEN ''Work Mission''
                    WHEN WP.EMPLOYEE_ID IS NOT NULL AND WP.PERMIT_TYPE = ''PERMISSION''
                        THEN ''Absent - Permission''
                    WHEN WP.EMPLOYEE_ID IS NOT NULL AND WP.' || 'PERMIT_TYPE = ''RECALL''
                        THEN ''Absent - Recall''
                    WHEN AB.EMPLOYEE_ID IS NOT NULL 
                        THEN ''Registered Absence''
                    WHEN PH.EMPLOYEE_ID IS NOT NULL 
                        THEN ''Public Holiday''
                    WHEN CD.EMPLOYEE_ID IS NOT NULL 
                        THEN ''Compensatory Day''
                    WHEN WO.EMPLOYEE_ID IS NOT NULL 
                        THEN ''Weekly Off''
                    ELSE ''Not Present''
                END AS STATUS_EN,

                -- ===== IS DISABLED ACTION =====
                CASE
                    WHEN CTO.EMPLOYEE_ID IS NOT NULL THEN 1
                    WHEN OT.EMPLOYEE_ID IS NOT NULL THEN 1
                    WHEN WP.EMPLOYEE_ID IS NOT NULL THEN 1
                    WHEN MS.EMPLOYEE_ID IS NOT NULL THEN 1
                    WHEN AB.EMPLOYEE_ID IS NOT NULL THEN 1
                    -- Leaves, Holiday, Weekly Off, Compensatory days D' || 'O NOT disable actions
                    ELSE 0
                END AS IS_DISABLED_ACTION,

                -- ===== CTO DETAILS =====
                CTO.CTO_ID,
                CTO.CTO_HOURS,

                -- ===== OVERTIME DETAILS =====
                OT.OT_ID,
                OT.OT_FROM_TIME,
                OT.OT_TO_TIME

            FROM HR_EMPLOYEES E

            -- ── الأقسام تحت المدير ──
            JOIN (
                SELECT D.ID           AS DEPT_ID,
                       D.ARABIC_NAME  AS DEPT_NAME
                FROM   HR_DEPARTMENT D
                START WITH D.MANAGER_ID = l_employee_id
                CONNECT BY PRIOR D.ID   = D.PARENT_ID
            ) DEPT_HIER ON DEPT_HIER.DEPT_ID = E.DEPARTMENT_ID

            -- ── بيانات الحضور ──
            LEFT JOIN (
                SELECT EMPLOYEE_ID, HAS_IN, HAS_OUT,
                       CHECK_IN_TIME, CHECK_OUT_TIME
                FROM   VW_ATTENDANCE_LOG
                WHERE  TR' || 'UNC(ATTENDANCE_DATE) = TRUNC(l_date_filter)
            ) A ON A.EMPLOYEE_ID = E.EMPLOYEE_ID

            -- ── بدل يعوض ──
            LEFT JOIN (
                SELECT EMPLOYEE_ID,
                       ID AS CTO_ID,
                       CTO_HOURS
                FROM   HR_CTO_TRANSACTIONS
                WHERE  STATUS = 1
                AND    TRUNC(CTO_DATE) = TRUNC(l_date_filter)
            ) CTO ON CTO.EMPLOYEE_ID = E.EMPLOYEE_ID

            -- ── إضافي أجر ──
            LEFT JOIN (
                SELECT EMPLOYEE_ID,
                       ID AS OT_ID,
                       FROM_TIME AS OT_FROM_TIME,
                       TO_TIME AS OT_TO_TIME
                FROM   HR_OVERTIME_REQUESTS
                WHERE  STATUS = ''1''
                AND    TRUNC(OVERTIME_DATE) = TRUNC(l_date_filter)
            ) OT ON OT.EMPLOYEE_ID = E.EMPLOYEE_ID

            -- ── تصريح عمل (استئذان أو استدعاء) ──
            LEFT JOIN (
                SELECT EMPLOYE' || 'E_ID, PERMIT_TYPE
                FROM   HR_WORK_PERMITS
                WHERE  STATUS = 1 
                AND    TRUNC(PERMIT_DATE) = TRUNC(l_date_filter)
            ) WP ON WP.EMPLOYEE_ID = E.EMPLOYEE_ID

            -- ── مهمة عمل ──
            LEFT JOIN (
                SELECT EMPLOYEE_ID
                FROM   HR_EMPLOYEE_MISSIONS
                WHERE  STATUS_ID IN (1, 4)
                AND    TRUNC(l_date_filter) BETWEEN TRUNC(START_DATE) AND TRUNC(NVL(END_DATE, START_DATE))
            ) MS ON MS.EMPLOYEE_ID = E.EMPLOYEE_ID

            -- ── بيانات الإجازة ──
            LEFT JOIN (
                SELECT LR.EMPLOYEE_ID,
                       LT.ARABIC_NAME  AS LEAVE_TYPE_AR,
                       LT.NAME         AS LEAVE_TYPE_EN
                FROM   HR_EMPLOYEE_LEAVE_REQUESTS LR
                JOIN   HR_LEAVE_TYPES LT ON LT.ID = LR.LEAVE_TYPE_ID
                WHERE  LR.STATUS_ID = 4
                AND    TRUNC(l_date_filter) BETWEEN TRUNC(LR' || '.START_DATE) AND TRUNC(LR.END_DATE)
            ) LV ON LV.EMPLOYEE_ID = E.EMPLOYEE_ID

            -- ── بيانات الغياب ──
            LEFT JOIN (
                SELECT EMPLOYEE_ID
                FROM   HR_ABSENCE_LOG
                WHERE  STATUS = ''1''
                AND    TRUNC(l_date_filter) BETWEEN TRUNC(ABSENCE_DATE) AND TRUNC(NVL(END_DATE, ABSENCE_DATE))
            ) AB ON AB.EMPLOYEE_ID = E.EMPLOYEE_ID

            -- ── عطلة رسمية ──
            LEFT JOIN (
                SELECT E2.EMPLOYEE_ID
                FROM   HR_EMPLOYEES E2
                JOIN   HR_OFFICIAL_HOLIDAYS H
                    ON  TRUNC(H.HOLIDAY_DATE) = TRUNC(l_date_filter)
                    AND H.STATUS = 1
                    AND (H.RELIGION_ID IS NULL OR H.RELIGION_ID = E2.RELIGION)
                    AND (H.SHIFT_ID IS NULL OR H.SHIFT_ID = E2.WORK_SHIFT_ID)
            ) PH ON PH.EMPLOYEE_ID = E.EMPLOYEE_ID

            -- ── راحة مستحقة ──
            LEFT JOIN (
      ' || '          SELECT E2.EMPLOYEE_ID
                FROM   HR_EMPLOYEES E2
                JOIN   VW_SHIFT_COMPENSATORY_DAYS CD2
                    ON  CD2.WORK_SHIFT_ID = E2.WORK_SHIFT_ID
                    AND TRUNC(CD2.COMP_DATE) = TRUNC(l_date_filter)
            ) CD ON CD.EMPLOYEE_ID = E.EMPLOYEE_ID

            -- ── راحة أسبوعية ──
            LEFT JOIN (
                SELECT DISTINCT E3.EMPLOYEE_ID
                FROM   HR_EMPLOYEES E3
                JOIN   HR_WORK_SHIF_DAYS SD
                    ON  SD.SHIFT_ID = E3.WORK_SHIFT_ID
                    AND SD.IS_OFF = 1
                    AND SD.DAY_ID = MOD(
                            TRUNC(l_date_filter) - (
                                SELECT TRUNC(WEEK_REF_DATE)
                                FROM   SYSTEM_SETTINGS
                                WHERE  ROWNUM = 1
                            ), 7) + 1
            ) WO ON WO.EMPLOYEE_ID = E.EMPLOYEE_ID

            WHERE E.STATUS = 1 -- الفلترة ' || 'بحالة الموظف (تم إلغاء استثناء المدير)
            ORDER BY DEPT_HIER.DEPT_NAME, E.FULL_NAME_AR
        ) LOOP
            APEX_JSON.open_object;
                APEX_JSON.write(''employeeId'',        rec.EMPLOYEE_ID,        p_write_null => TRUE);
                APEX_JSON.write(''employeeCode'',      rec.EMPLOYEE_CODE,      p_write_null => TRUE);
                APEX_JSON.write(''nameAr'',            rec.FULL_NAME_AR,       p_write_null => TRUE);
                APEX_JSON.write(''nameEn'',            rec.FULL_NAME_EN,       p_write_null => TRUE);
                APEX_JSON.write(''departmentName'',    rec.DEPARTMENT_NAME,    p_write_null => TRUE);
                APEX_JSON.write(''checkInTime'',       rec.CHECK_IN_TIME,      p_write_null => TRUE);
                APEX_JSON.write(''checkOutTime'',      rec.CHECK_OUT_TIME,     p_write_null => TRUE);
                APEX_JSON.write(''workingHours'',      rec.WORKING_HOURS,      p_write_null => TRUE);
                APEX_JSON.write(''attendanc' || 'eStatus'',  rec.ATTENDANCE_STATUS,  p_write_null => TRUE);
                APEX_JSON.write(''statusAr'',          rec.STATUS_AR,          p_write_null => TRUE);
                APEX_JSON.write(''statusEn'',          rec.STATUS_EN,          p_write_null => TRUE);
                APEX_JSON.write(''isDisabledAction'',  rec.IS_DISABLED_ACTION, p_write_null => TRUE);

                IF rec.CTO_ID IS NOT NULL THEN
                    APEX_JSON.open_object(''cto'');
                        APEX_JSON.write(''id'',    rec.CTO_ID,    p_write_null => TRUE);
                        APEX_JSON.write(''hours'', rec.CTO_HOURS, p_write_null => TRUE);
                    APEX_JSON.close_object;
                END IF;

                IF rec.OT_ID IS NOT NULL THEN
                    APEX_JSON.open_object(''overtime'');
                        APEX_JSON.write(''id'',       rec.OT_ID,          p_write_null => TRUE);
                        APEX_JSON.write(''fromTime'', rec.OT_FROM_TIME,   p_write_null => TR' || 'UE);
                        APEX_JSON.write(''toTime'',   rec.OT_TO_TIME,     p_write_null => TRUE);
                    APEX_JSON.close_object;
                END IF;

            APEX_JSON.close_object;
        END LOOP;

        APEX_JSON.close_array;
    APEX_JSON.close_object;

EXCEPTION
    WHEN OTHERS THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                        p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''حدث خطأ في النظام'',            p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''An unexpected error occurred'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''SYSTEM_ERROR'',                 p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 500;
END;
');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'MyEmployees',
      p_pattern        => 'Missions',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => NULL);

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'MyEmployees',
      p_pattern        => 'Missions',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'-- ============================================================
-- POST /api/v1/hr/missions
-- Module  : api/v1
-- Template: hr/missions
-- Method  : POST
-- Auth    : Token Required
-- Body    : employeeId, startDate, endDate, missionType,
--           destination, missionPurpose, notes
-- ============================================================
DECLARE
    l_header_value    VARCHAR2(4000);
    l_bearer_token    VARCHAR2(4000);
    l_token           APEX_JWT.T_TOKEN;
    l_user_object     APEX_JSON.T_VALUES;
    l_user_id         NUMBER;
    l_user_type       VARCHAR2(200);
    l_iss             VARCHAR2(200);

    l_body            CLOB;
    l_body_values     APEX_JSON.T_VALUES;

    l_username        VARCHAR2(200);
    l_company_id      NUMBER;
    l_branch_id       NUMBER;

    -- Body Variables
    l_employee_id     NUMBER;
    l_start_date      DATE;
    l_end_date        DATE;
    l_mission_type    VARCHAR2(20);
    l_destination     VARCHAR2(20' || '0);
    l_mission_purpose VARCHAR2(500);
    l_notes           VARCHAR2(1000);

    -- Work Variables
    l_new_id          NUMBER;
    l_emp_check       NUMBER := 0;

BEGIN
    -- ===== 1. TOKEN VALIDATION =====
    l_header_value := OWA_UTIL.get_cgi_env(''Authorization'');

    IF l_header_value IS NULL OR INSTR(l_header_value, ''Bearer '') != 1 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''يرجى تسجيل الدخول أولاً'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Authentication required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''TOKEN_REQUIRED'',         p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 401;
        RETURN;
    END IF;

    l_bearer_token := SUBSTR(l_header_value, 8);

    BEGIN
        l_token := APEX_JWT.DECODE(
            p_value         => l_bearer_token,
            p_si' || 'gnature_key => SYS.UTL_RAW.CAST_TO_RAW(''secretKey'')
        );
        APEX_JSON.PARSE(l_user_object, l_token.payload);

        IF NOT APEX_JSON.DOES_EXIST(p_path => ''sub'', p_values => l_user_object) THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_iss := APEX_JSON.GET_VARCHAR2(p_path => ''iss'', p_values => l_user_object);

        IF l_iss IS NULL OR l_iss != ''ORDS'' THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'',' || ' p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_user_id   := TO_NUMBER(APEX_JSON.GET_VARCHAR2(p_path => ''sub'', p_values => l_user_object));
        l_user_type :=           APEX_JSON.GET_VARCHAR2(p_path => ''aud'', p_values => l_user_object);

    EXCEPTION
        WHEN OTHERS THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
' || '    END;

    -- ===== 2. GET USER INFO =====
    BEGIN
        SELECT U.USERNAME, U.DEFAULT_COMPANY_ID, U.DEFAULT_BRANCH_ID
        INTO   l_username, l_company_id, l_branch_id
        FROM   SEC_USERS U
        WHERE  U.ID = l_user_id
        AND    ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',               p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''المستخدم غير موجود'',   p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''User not found'',      p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''USER_NOT_FOUND'',       p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 404;
            RETURN;
    END;

    -- ===== 3. READ BODY =====
    l_body := :body_text;

    IF l_body IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                      p' || '_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''لم نتمكن من قراءة البيانات'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Request body is empty'',      p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''INVALID_REQUEST'',            p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    APEX_JSON.PARSE(l_body_values, l_body);

    -- ===== 4. EXTRACT PARAMS =====
    l_employee_id     := APEX_JSON.GET_NUMBER(p_path => ''employeeId'', p_values => l_body_values);
    l_start_date      := TO_DATE(TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''startDate'',      p_values => l_body_values)), ''DD/MM/YYYY'');
    l_end_date        := TO_DATE(TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''endDate'',        p_values => l_body_values)), ''DD/MM/YYYY'');
    l_mission_type    := UPPER(TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''missionType'',    p_values => l_body_values)));
    l_destination     := TRIM(APEX_JSON.GET_' || 'VARCHAR2(p_path => ''destination'',     p_values => l_body_values));
    l_mission_purpose := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''missionPurpose'',  p_values => l_body_values));
    l_notes           := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''notes'',           p_values => l_body_values));

    -- ===== 5. VALIDATE REQUIRED =====
    IF l_employee_id IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''رقم الموظف مطلوب'',        p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''employeeId is required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',           p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_start_date IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                 p_write_null => TRUE);
      ' || '  APEX_JSON.write(''messageAr'', ''تاريخ البداية مطلوب'',   p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''startDate is required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',          p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_end_date IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',               p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''تاريخ النهاية مطلوب'',  p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''endDate is required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',        p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_mission_type IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                   p_write_null => TRUE);
        A' || 'PEX_JSON.write(''messageAr'', ''نوع المهمة مطلوب'',         p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''missionType is required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',            p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_mission_type NOT IN (''INTERNAL'', ''EXTERNAL'') THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                                    p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''نوع المهمة يجب أن يكون INTERNAL أو EXTERNAL'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''missionType must be INTERNAL or EXTERNAL'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''INVALID_DATA'',                             p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_end_date < l_start_date THEN
        A' || 'PEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                                    p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''تاريخ النهاية يجب أن يكون بعد تاريخ البداية'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''endDate must be after startDate'',          p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''INVALID_DATE_RANGE'',                       p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    -- ===== 6. CHECK EMPLOYEE EXISTS =====
    SELECT COUNT(*) INTO l_emp_check
    FROM   HR_EMPLOYEES
    WHERE  EMPLOYEE_ID = l_employee_id;

    IF l_emp_check = 0 THEN
