  ORDS.DEFINE_HANDLER(
      p_module_name    => 'MyEmployees',
      p_pattern        => 'Overtime',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'-- ============================================================
-- POST /api/v1/hr/overtime
-- Module  : api/v1
-- Template: hr/overtime
-- Method  : POST
-- Auth    : Token Required
-- Body    : employeeId, overtimeDate, fromTime, toTime, notes
-- ============================================================
DECLARE
    l_header_value    VARCHAR2(4000);
    l_bearer_token    VARCHAR2(4000);
    l_token           APEX_JWT.T_TOKEN;
    l_user_object     APEX_JSON.T_VALUES;
    l_user_id         NUMBER;
    l_user_type       VARCHAR2(200);
    l_iss             VARCHAR2(200);

    l_body            CLOB;
    l_body_values     APEX_JSON.T_VALUES;

    l_username        VARCHAR2(200);
    l_company_id      NUMBER;
    l_branch_id       NUMBER;

    -- Body Variables
    l_employee_id     NUMBER;
    l_overtime_date   DATE;
    l_from_time       VARCHAR2(10);
    l_to_time         VARCHAR2(10);
    l_total_hours     NUMBER;
    l_notes           VARCHAR2(1000);
' || '

    -- Work Variables
    l_new_id          NUMBER;
    l_emp_check       NUMBER := 0;
    l_dup_check       NUMBER := 0;

BEGIN
    -- ===== 1. TOKEN VALIDATION =====
    l_header_value := OWA_UTIL.get_cgi_env(''Authorization'');

    IF l_header_value IS NULL OR INSTR(l_header_value, ''Bearer '') != 1 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''يرجى تسجيل الدخول أولاً'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Authentication required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''TOKEN_REQUIRED'',         p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 401;
        RETURN;
    END IF;

    l_bearer_token := SUBSTR(l_header_value, 8);

    BEGIN
        l_token := APEX_JWT.DECODE(
            p_value         => l_bearer_token,
            p_signature_key => SYS.UTL_RAW.CAST_TO_RAW(''secre' || 'tKey'')
        );
        APEX_JSON.PARSE(l_user_object, l_token.payload);

        IF NOT APEX_JSON.DOES_EXIST(p_path => ''sub'', p_values => l_user_object) THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_iss := APEX_JSON.GET_VARCHAR2(p_path => ''iss'', p_values => l_user_object);

        IF l_iss IS NULL OR l_iss != ''ORDS'' THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSO' || 'N.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_user_id   := TO_NUMBER(APEX_JSON.GET_VARCHAR2(p_path => ''sub'', p_values => l_user_object));
        l_user_type :=           APEX_JSON.GET_VARCHAR2(p_path => ''aud'', p_values => l_user_object);

    EXCEPTION
        WHEN OTHERS THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
    END;

    -- ===== 2. GET MANAGER INFO ' || '=====
    BEGIN
        SELECT U.USERNAME, U.DEFAULT_COMPANY_ID, U.DEFAULT_BRANCH_ID
        INTO   l_username, l_company_id, l_branch_id
        FROM   SEC_USERS U
        WHERE  U.ID = l_user_id
        AND    ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',               p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''المستخدم غير موجود'',   p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''User not found'',      p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''USER_NOT_FOUND'',       p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 404;
            RETURN;
    END;

    -- ===== 3. READ BODY =====
    l_body := :body_text;

    IF l_body IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                      p_write_null => TRUE);
        APEX_JSON.w' || 'rite(''messageAr'', ''لم نتمكن من قراءة البيانات'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Request body is empty'',      p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''INVALID_REQUEST'',            p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    APEX_JSON.PARSE(l_body_values, l_body);

    -- ===== 4. EXTRACT PARAMS =====
    l_employee_id   := APEX_JSON.GET_NUMBER(p_path => ''employeeId'',   p_values => l_body_values);
    l_overtime_date := TO_DATE(TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''overtimeDate'', p_values => l_body_values)), ''DD/MM/YYYY'');
    l_from_time     := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''fromTime'', p_values => l_body_values));
    l_to_time       := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''toTime'',   p_values => l_body_values));
    l_notes         := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''notes'',    p_values => l_body_values));

    -- ===== 5. VALIDATE REQUIR' || 'ED =====
    IF l_employee_id IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''رقم الموظف مطلوب'',        p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''employeeId is required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',           p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_overtime_date IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                     p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''تاريخ الساعات الإضافية مطلوب'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''overtimeDate is required'',  p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',              p_write_null => TRUE);
        APEX_JSON.close_object;
        :status :' || '= 400;
        RETURN;
    END IF;

    IF l_from_time IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                 p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''وقت البداية مطلوب'',     p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''fromTime is required'',  p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',          p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_to_time IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',               p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''وقت النهاية مطلوب'',   p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''toTime is required'',  p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',        p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
  ' || '      RETURN;
    END IF;

    -- ===== 6. VALIDATE TIME LOGIC =====
    IF TO_DATE(l_to_time, ''HH24:MI'') <= TO_DATE(l_from_time, ''HH24:MI'') THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                                    p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''وقت النهاية يجب أن يكون بعد وقت البداية'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''toTime must be after fromTime'',            p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''INVALID_TIME_RANGE'',                       p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    -- ===== 7. CALCULATE TOTAL HOURS =====
    l_total_hours := ROUND(
        (TO_DATE(l_to_time, ''HH24:MI'') - TO_DATE(l_from_time, ''HH24:MI'')) * 24,
        2
    );

    -- ===== 8. CHECK EMPLOYEE EXISTS =====
    SELECT COUNT(*) INTO l_emp_check
    FROM   HR_EMPLOYEES
    WHERE  EMPLOYEE_ID =' || ' l_employee_id;

    IF l_emp_check = 0 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',               p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''الموظف غير موجود'',    p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Employee not found'',  p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''EMPLOYEE_NOT_FOUND'',  p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 404;
        RETURN;
    END IF;

    -- ===== 9. CHECK DUPLICATE =====
    SELECT COUNT(*) INTO l_dup_check
    FROM   HR_OVERTIME_REQUESTS
    WHERE  EMPLOYEE_ID             = l_employee_id
    AND    TRUNC(OVERTIME_DATE)    = TRUNC(l_overtime_date)
    AND    STATUS                  = ''1''
    AND    (
               (l_from_time >= FROM_TIME AND l_from_time < TO_TIME)
            OR (l_to_time   >  FROM_TIME AND l_to_time  <= TO_TIME)
            OR (l_from_time <= FROM_TIME AND l_to_time  >= TO_TIME)
        ' || '   );

    IF l_dup_check > 0 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                                           p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''يوجد طلب ساعات إضافية متداخل لهذا الموظف في نفس اليوم'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''An overlapping overtime request exists for this employee'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''DUPLICATE_OVERTIME'',                              p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 409;
        RETURN;
    END IF;

    -- ===== 10. INSERT =====
    INSERT INTO HR_OVERTIME_REQUESTS (
        COMPANY_ID,
        BRANCH_ID,
        EMPLOYEE_ID,
        OVERTIME_DATE,
        FROM_TIME,
        TO_TIME,
        TOTAL_HOURS,
        NOTES,
        STATUS,
        CREATED_BY,
        CREATED_BY_USER_ID,
        CREATED_DATE
    ) VALUES (
        l_company_id,
        l_branc' || 'h_id,
        l_employee_id,
        l_overtime_date,
        l_from_time,
        l_to_time,
        l_total_hours,
        l_notes,
        ''1'',
        l_username,
        l_user_id,
        SYSDATE
    ) RETURNING ID INTO l_new_id;

    COMMIT;

    -- ===== 11. SUCCESS RESPONSE =====
    :status := 201;
    APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''success'',                              p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''تم تسجيل الساعات الإضافية بنجاح'',     p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Overtime request recorded successfully'', p_write_null => TRUE);
        APEX_JSON.open_object(''overtime'');
            APEX_JSON.write(''id'',           l_new_id,                                p_write_null => TRUE);
            APEX_JSON.write(''employeeId'',   l_employee_id,                           p_write_null => TRUE);
            APEX_JSON.write(''overtimeDate'', TO_CHAR(l_overtime_date, ''DD/MM/YYY' || 'Y''),  p_write_null => TRUE);
            APEX_JSON.write(''fromTime'',     l_from_time,                             p_write_null => TRUE);
            APEX_JSON.write(''toTime'',       l_to_time,                               p_write_null => TRUE);
            APEX_JSON.write(''totalHours'',   l_total_hours,                           p_write_null => TRUE);
            APEX_JSON.write(''notes'',        l_notes,                                 p_write_null => TRUE);
            APEX_JSON.write(''status'',       ''1'',                                     p_write_null => TRUE);
        APEX_JSON.close_object;
    APEX_JSON.close_object;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                        p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''حدث خطأ في النظام'',            p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''An unexpected error occurred'', p_write_null => TRUE);' || '
        APEX_JSON.write(''errorCode'', ''SYSTEM_ERROR'',                 p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 500;
END;');

