        APEX_JSON.write(''messageEn'', ''Request body is empty'',      p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''INVALID_REQUEST'',            p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    APEX_JSON.PARSE(l_body_values, l_body);

    l_trip_id   := APEX_JSON.GET_NUMBER(p_path => ''tripId'',   p_values => l_body_values);
    l_latitude  := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''latitude'',  p_values => l_body_values));
    l_longitude := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''longitude'', p_values => l_body_values));
    l_is_fake   := NVL(APEX_JSON.GET_NUMBER(p_path => ''isFake'', p_values => l_body' || '_values), 0);
    l_notes     := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''notes'', p_values => l_body_values));

    -- ===== 4. VALIDATE REQUIRED =====
    IF l_trip_id IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',              p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''رقم الرحلة مطلوب'',   p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''tripId is required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',       p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_latitude IS NULL OR l_longitude IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                              p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''الموقع الجغرافي مطلوب'',              p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''latitude and longitude are required'',' || ' p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAMS'',                     p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    -- ===== 5. CHECK TRIP EXISTS & BELONGS TO EMPLOYEE =====
    BEGIN
        SELECT STATUS, EMPLOYEE_ID, START_LATITUDE, START_LONGITUDE
        INTO   l_status, l_trip_employee, l_start_lat, l_start_lng
        FROM   HR_EMPLOYEE_TRIPS
        WHERE  ID = l_trip_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',              p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''الرحلة غير موجودة'',  p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Trip not found'',     p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''TRIP_NOT_FOUND'',      p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 404;
          ' || '  RETURN;
    END;

    IF l_trip_employee != l_employee_id THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                          p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''لا يمكنك الوصول لهذه الرحلة'',     p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''You cannot access this trip'',    p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''FORBIDDEN'',                      p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 403;
        RETURN;
    END IF;

    -- ===== 6. CHECK STATUS = STARTED =====
    IF l_status != ''STARTED'' THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''لا يمكن إنهاء هذه الرحلة، حالتها الحالية '' || l_status, p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Cannot end this trip, current status is '' || l_status, p' || '_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''INVALID_TRIP_STATUS'',                    p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    -- ===== 7. CALCULATE TOTAL_DISTANCE =====
    -- جلب عدد نقاط التتبع
    SELECT COUNT(*) INTO l_points_count
    FROM   HR_EMPLOYEE_TRIP_LOCATIONS
    WHERE  TRIP_ID = l_trip_id;

    IF l_points_count > 1 THEN
        -- فيه نقاط تتبع → اجمع المسافة بين كل نقطة والتالية (Haversine)
        l_total_distance := 0;
        l_prev_lat := NULL;
        l_prev_lng := NULL;

        FOR rec IN (
            SELECT TO_NUMBER(LATITUDE) AS LAT, TO_NUMBER(LONGITUDE) AS LNG
            FROM   HR_EMPLOYEE_TRIP_LOCATIONS
            WHERE  TRIP_ID = l_trip_id
            ORDER BY RECORDED_AT
        ) LOOP
            IF l_prev_lat IS NOT NULL THEN
                l_total_distance := l_total_distance +
                    6371000 * ACOS(
                       ' || ' LEAST(1, GREATEST(-1,
                            SIN(l_prev_lat * 3.141592653589793 / 180) * SIN(rec.LAT * 3.141592653589793 / 180)
                          + COS(l_prev_lat * 3.141592653589793 / 180) * COS(rec.LAT * 3.141592653589793 / 180)
                          * COS((rec.LNG - l_prev_lng) * 3.141592653589793 / 180)
                        ))
                    );
            END IF;
            l_prev_lat := rec.LAT;
            l_prev_lng := rec.LNG;
        END LOOP;

    ELSE
        -- مفيش نقاط تتبع كافية → احسب مسافة مباشرة بين البداية والنهاية
        IF l_start_lat IS NOT NULL AND l_start_lng IS NOT NULL THEN
            l_curr_lat := TO_NUMBER(l_latitude);
            l_curr_lng := TO_NUMBER(l_longitude);
            l_prev_lat := TO_NUMBER(l_start_lat);
            l_prev_lng := TO_NUMBER(l_start_lng);

            l_total_distance :=
                6371000 * ACOS(
                    LEAST(1, GREATEST(-1,
                        SIN(l_prev_l' || 'at * 3.141592653589793 / 180) * SIN(l_curr_lat * 3.141592653589793 / 180)
                      + COS(l_prev_lat * 3.141592653589793 / 180) * COS(l_curr_lat * 3.141592653589793 / 180)
                      * COS((l_curr_lng - l_prev_lng) * 3.141592653589793 / 180)
                    ))
                );
        ELSE
            l_total_distance := 0;
        END IF;
    END IF;

    -- ===== 8. UPDATE TRIP =====
    UPDATE HR_EMPLOYEE_TRIPS
    SET    STATUS         = ''COMPLETED'',
           END_TIME        = SYSDATE,
           END_LATITUDE    = l_latitude,
           END_LONGITUDE   = l_longitude,
           TOTAL_DISTANCE  = ROUND(l_total_distance, 2),
           IS_FAKE         = CASE WHEN IS_FAKE = 1 OR l_is_fake = 1 THEN 1 ELSE 0 END,
           NOTES           = CASE WHEN l_notes IS NOT NULL THEN l_notes ELSE NOTES END
    WHERE  ID = l_trip_id;

    COMMIT;

    -- ===== 9. SUCCESS RESPONSE =====
    :status := 200;
    APEX_JSON.open_object;
       ' || ' APEX_JSON.write(''status'',    ''success'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''تم إنهاء الرحلة بنجاح'',    p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Trip ended successfully'',  p_write_null => TRUE);
        APEX_JSON.open_object(''trip'');
            APEX_JSON.write(''id'',             l_trip_id,                              p_write_null => TRUE);
            APEX_JSON.write(''status'',         ''COMPLETED'',                            p_write_null => TRUE);
            APEX_JSON.write(''endTime'',        TO_CHAR(SYSDATE, ''DD/MM/YYYY HH24:MI:SS''), p_write_null => TRUE);
            APEX_JSON.write(''endLatitude'',    l_latitude,                             p_write_null => TRUE);
            APEX_JSON.write(''endLongitude'',   l_longitude,                            p_write_null => TRUE);
            APEX_JSON.write(''totalDistance'',  ROUND(l_total_distance, 2),             p_write_null => TRUE);
        APEX_JSON.close_object;
    ' || 'APEX_JSON.close_object;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                        p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''حدث خطأ في النظام'',            p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''An unexpected error occurred'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''SYSTEM_ERROR'',                 p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 500;
END;');

  ORDS.DEFINE_TEMPLATE(
