  ORDS.DEFINE_HANDLER(
      p_module_name    => 'Trips',
      p_pattern        => 'MyTrips',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'-- ============================================================
-- GET /api/v1/trips/my
-- Module  : api/v1
-- Template: trips/my
-- Method  : GET
-- Auth    : Token Required
-- Query   : ?page=1&pageSize=20&status=STARTED (اختياري)
-- ============================================================
DECLARE
    l_header_value    VARCHAR2(4000);
    l_bearer_token    VARCHAR2(4000);
    l_token           APEX_JWT.T_TOKEN;
    l_user_object     APEX_JSON.T_VALUES;
    l_user_id         NUMBER;
    l_user_type       VARCHAR2(200);
    l_iss             VARCHAR2(200);

    l_employee_id     NUMBER;

    l_status_filter   VARCHAR2(15);
    l_page            NUMBER;
    l_page_size       NUMBER;
    l_total           NUMBER := 0;

BEGIN
    -- ===== 1. TOKEN VALIDATION =====
    l_header_value := OWA_UTIL.get_cgi_env(''Authorization'');

    IF l_header_value IS NULL OR INSTR(l_header_value, ''Bearer '') != 1 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''' || 'status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''يرجى تسجيل الدخول أولاً'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Authentication required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''TOKEN_REQUIRED'',         p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 401;
        RETURN;
    END IF;

    l_bearer_token := SUBSTR(l_header_value, 8);

    BEGIN
        l_token := APEX_JWT.DECODE(
            p_value         => l_bearer_token,
            p_signature_key => SYS.UTL_RAW.CAST_TO_RAW(''secretKey'')
        );
        APEX_JSON.PARSE(l_user_object, l_token.payload);

        IF NOT APEX_JSON.DOES_EXIST(p_path => ''sub'', p_values => l_user_object) THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
        ' || '    APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_iss := APEX_JSON.GET_VARCHAR2(p_path => ''iss'', p_values => l_user_object);

        IF l_iss IS NULL OR l_iss != ''ORDS'' THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_user_id   := TO_NUMBER(APEX_JSON.GET_VARCHAR2(p_path => ''sub'', p_values => l_user_object));
        l_user_type :' || '=           APEX_JSON.GET_VARCHAR2(p_path => ''aud'', p_values => l_user_object);

    EXCEPTION
        WHEN OTHERS THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
    END;

    -- ===== 2. GET EMPLOYEE_ID =====
    BEGIN
        SELECT E.EMPLOYEE_ID
        INTO   l_employee_id
        FROM   SEC_USERS U
        JOIN   HR_EMPLOYEES E
            ON U.USER_TYPE    = ''EMPLOYEE''
            AND E.EMPLOYEE_ID = U.REFERENCE_USER_ID
        WHERE  U.ID = l_user_id
        AND    ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            APEX_JSON.open_object;' || '
            APEX_JSON.write(''status'',    ''error'',                          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''المستخدم غير مرتبط بموظف'',       p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''User is not linked to employee'', p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''EMPLOYEE_NOT_LINKED'',            p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 400;
            RETURN;
    END;

    -- ===== 3. READ QUERY PARAMS =====
    l_status_filter := UPPER(:status_filter);  -- ?status=STARTED
    l_page          := NVL(:page, 1);
    l_page_size     := NVL(:pageSize, 20);

    -- ===== 4. GET TOTAL COUNT =====
    SELECT COUNT(*) INTO l_total
    FROM   HR_EMPLOYEE_TRIPS
    WHERE  EMPLOYEE_ID = l_employee_id
    AND    (l_status_filter IS NULL OR STATUS = l_status_filter);

    -- ===== 5. SUCCESS RESPONSE =====
    :status := 200;
    APEX_JSON.open_object;
        A' || 'PEX_JSON.write(''status'',    ''success'',              p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''تم جلب الرحلات بنجاح'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Trips retrieved successfully'', p_write_null => TRUE);

        APEX_JSON.open_array(''trips'');

        FOR rec IN (
            SELECT *
            FROM (
                SELECT
                    T.ID,
                    T.DESCRIPTION,
                    T.TRIP_DATE,
                    T.START_TIME,
                    T.END_TIME,
                    T.CODE,                   
                    T.TRIP_TYPE,
                    T.STATUS,
                    T.START_LATITUDE,
                    T.START_LONGITUDE,
                    T.END_LATITUDE,
                    T.END_LONGITUDE,
                    T.IS_FAKE,
                    T.TOTAL_DISTANCE,
                    T.SITE_ID,
                    S.NAME        AS SITE_NAME_EN,
                    S.ARABI' || 'C_NAME AS SITE_NAME_AR,
                    T.CANCELLED_REASON,
                    T.NOTES,
                    ROW_NUMBER() OVER (ORDER BY T.ID DESC) AS RN
                FROM HR_EMPLOYEE_TRIPS T
                LEFT JOIN HR_SITES S ON S.ID = T.SITE_ID
                WHERE T.EMPLOYEE_ID = l_employee_id
                AND   (l_status_filter IS NULL OR T.STATUS = l_status_filter)
            )
            WHERE RN BETWEEN ((l_page - 1) * l_page_size + 1) AND (l_page * l_page_size)
            ORDER BY RN
        ) LOOP
            APEX_JSON.open_object;
                APEX_JSON.write(''id'',              rec.ID,                              p_write_null => TRUE);
                APEX_JSON.write(''code'',     rec.CODE,                     p_write_null => TRUE);
                APEX_JSON.write(''description'',     rec.DESCRIPTION,                     p_write_null => TRUE);
                APEX_JSON.write(''tripDate'',        TO_CHAR(rec.TRIP_DATE, ''DD/MM/YYYY''), p_write_null ' || '=> TRUE);
                APEX_JSON.write(''startTime'',       TO_CHAR(rec.START_TIME, ''DD/MM/YYYY HH24:MI''), p_write_null => TRUE);
                APEX_JSON.write(''endTime'',         TO_CHAR(rec.END_TIME,   ''DD/MM/YYYY HH24:MI''), p_write_null => TRUE);
                APEX_JSON.write(''tripType'',        rec.TRIP_TYPE,                       p_write_null => TRUE);
                APEX_JSON.write(''status'',          rec.STATUS,                          p_write_null => TRUE);
                APEX_JSON.write(''startLatitude'',   rec.START_LATITUDE,                  p_write_null => TRUE);
                APEX_JSON.write(''startLongitude'',  rec.START_LONGITUDE,                 p_write_null => TRUE);
                APEX_JSON.write(''endLatitude'',     rec.END_LATITUDE,                    p_write_null => TRUE);
                APEX_JSON.write(''endLongitude'',    rec.END_LONGITUDE,                   p_write_null => TRUE);
                APEX_JSON.write(''isFake'',          rec.IS_FAKE,          ' || '               p_write_null => TRUE);
                APEX_JSON.write(''totalDistance'',   rec.TOTAL_DISTANCE,                  p_write_null => TRUE);
                APEX_JSON.write(''cancelledReason'', rec.CANCELLED_REASON,                p_write_null => TRUE);
                APEX_JSON.write(''notes'',           rec.NOTES,                           p_write_null => TRUE);

                APEX_JSON.open_object(''site'');
                    APEX_JSON.write(''id'',     rec.SITE_ID,      p_write_null => TRUE);
                    APEX_JSON.write(''nameEn'', rec.SITE_NAME_EN, p_write_null => TRUE);
                    APEX_JSON.write(''nameAr'', rec.SITE_NAME_AR, p_write_null => TRUE);
                APEX_JSON.close_object;
            APEX_JSON.close_object;
        END LOOP;

        APEX_JSON.close_array;

        APEX_JSON.write(''total'',    l_total,    p_write_null => TRUE);
        APEX_JSON.write(''page'',     l_page,     p_write_null => TRUE);
        APEX_JSON.write(''pageSize''' || ', l_page_size, p_write_null => TRUE);

    APEX_JSON.close_object;

EXCEPTION
    WHEN OTHERS THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                        p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''حدث خطأ في النظام'',            p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''An unexpected error occurred'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''SYSTEM_ERROR'',                 p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 500;
END;');

