    l_phone_number    VARCHAR2(20);

BEGIN
    -- ===== 1. TOKEN VALIDATION =====
    l_header_value := OWA_UTIL.get_cgi_env(''Authorization'');

    I' || 'F l_header_value IS NULL OR INSTR(l_header_value, ''Bearer '') != 1 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''يرجى تسجيل الدخول أولاً'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Authentication required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''TOKEN_REQUIRED'',         p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 401;
        RETURN;
    END IF;

    l_bearer_token := SUBSTR(l_header_value, 8);

    BEGIN
        l_token := APEX_JWT.DECODE(
            p_value         => l_bearer_token,
            p_signature_key => SYS.UTL_RAW.CAST_TO_RAW(''secretKey'')
        );
        APEX_JSON.PARSE(l_user_object, l_token.payload);

        IF NOT APEX_JSON.DOES_EXIST(p_path => ''sub'', p_values => l_user_object) THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''err' || 'or'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF;

        l_iss := APEX_JSON.GET_VARCHAR2(p_path => ''iss'', p_values => l_user_object);

        IF l_iss IS NULL OR l_iss != ''ORDS'' THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
        END IF' || ';

        l_user_id   := TO_NUMBER(APEX_JSON.GET_VARCHAR2(p_path => ''sub'', p_values => l_user_object));
        l_user_type :=           APEX_JSON.GET_VARCHAR2(p_path => ''aud'', p_values => l_user_object);

    EXCEPTION
        WHEN OTHERS THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.write(''errorCode'', ''INVALID_TOKEN'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
    END;

    -- ===== 2. READ BODY =====
    l_body := :body_text;

    IF l_body IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                      p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''لم نتمكن من قراءة البيانات'', ' || 'p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Request body is empty'',      p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''INVALID_REQUEST'',            p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    APEX_JSON.PARSE(l_body_values, l_body);

    -- ===== 3. EXTRACT PARAMS =====
    l_device_token := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''deviceToken'',  p_values => l_body_values));
    l_device_type  := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''deviceType'',   p_values => l_body_values));
    l_device_name  := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''deviceName'',   p_values => l_body_values));
    l_app_version  := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''appVersion'',   p_values => l_body_values));
    l_phone_number := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''phoneNumber'',  p_values => l_body_values));

    -- ===== 4. VALIDATE REQUIRED =====
    IF l_device_token IS NULL AND l_device_typ' || 'e IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                             p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''Device Token ونوع الجهاز مطلوبان'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''deviceToken and deviceType are required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAMS'',                   p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_device_token IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                   p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''Device Token مطلوب'',      p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''deviceToken is required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',           p_write_null => TRUE);
        APEX_JSON.close_object;
        :stat' || 'us := 400;
        RETURN;
    END IF;

    IF l_device_type IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                   p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''نوع الجهاز مطلوب'',        p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''deviceType is required'',  p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''MISSING_PARAM'',           p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    -- ===== 5. MERGE (INSERT OR UPDATE) =====
    MERGE INTO APP_FCM_USER_TOKENS T
    USING (SELECT l_user_id   AS USER_ID,
                  l_user_type AS USER_TYPE
           FROM DUAL) S
    ON (T.USER_ID = S.USER_ID AND T.USER_TYPE = S.USER_TYPE)

    WHEN MATCHED THEN
        UPDATE SET
            T.DEVICE_TOKEN  = l_device_token,
            T.DEVICE_TYPE   = l_device_type,
            T.DEVICE_NAME   = l_device_name,
   ' || '         T.APP_VERSION   = l_app_version,
            T.PHONE_NUMBER  = l_phone_number,
            T.IS_ACTIVE     = 1,
            T.LAST_USED     = SYSDATE,
            T.UPDATED       = SYSDATE,
            T.UPDATED_BY    = l_user_id

    WHEN NOT MATCHED THEN
        INSERT (
            USER_ID,
            USER_TYPE,
            PHONE_NUMBER,
            DEVICE_TOKEN,
            DEVICE_TYPE,
            DEVICE_NAME,
            APP_VERSION,
            IS_ACTIVE,
            LAST_USED,
            CREATED,
            CREATED_BY
        ) VALUES (
            l_user_id,
            l_user_type,
            l_phone_number,
            l_device_token,
            l_device_type,
            l_device_name,
            l_app_version,
            1,
            SYSDATE,
            SYSDATE,
            l_user_id
        );

    COMMIT;

    -- ===== 6. SUCCESS RESPONSE =====
    :status := 200;
    APEX_JSON.open_object;
        APEX_JSON.write' || '(''status'',    ''success'',                        p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''تم تسجيل الجهاز بنجاح'',          p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Device registered successfully'', p_write_null => TRUE);
    APEX_JSON.close_object;

EXCEPTION
    WHEN OTHERS THEN
