      p_source         => 
'DECLARE
    l_body            CLOB;
    l_body_values     APEX_JSON.T_VALUES;

    l_username        VARCHAR2(200);
    l_password        VARCHAR2(200);
    l_device_uuid     VARCHAR2(100);

    l_user_id         NUMBER;
    l_user_type       VARCHAR2(200);
    l_is_locked       VARCHAR2(10);
    l_user_status     VARCHAR2(10);
    l_is_mobile_app   VARCHAR2(10);
    l_stored_device_uuid VARCHAR2(100);
    l_check           NUMBER := 0;

    l_token           VARCHAR2(4000);
    l_rec             APP_USERS_LOGIN%ROWTYPE;

BEGIN
    -- ===== 1. READ BODY =====
    l_body := :body_text;

    IF l_body IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                      p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''لم نتمكن من قراءة البيانات'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Request body is empty'',      p_write_null => TRUE);
        APEX_JSON.close_object;
        :status :=' || ' 400;
        RETURN;
    END IF;

    APEX_JSON.PARSE(l_body_values, l_body);

    -- ===== 2. EXTRACT PARAMS =====
    l_username    := UPPER(TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''username'',   p_values => l_body_values)));
    l_password    :=       TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''password'',   p_values => l_body_values));
    l_device_uuid :=       TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''deviceUuid'', p_values => l_body_values));

    -- ===== 3. VALIDATE REQUIRED =====
    IF l_username IS NULL AND l_password IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                              p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''اسم المستخدم وكلمة المرور مطلوبان'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Username and password are required'', p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_username IS NULL THEN
' || '        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''اسم المستخدم مطلوب'',   p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Username is required'', p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    IF l_password IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''كلمة المرور مطلوبة'',   p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Password is required'', p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    -- ===== 4. CHECK USER EXISTS =====
    BEGIN
        SELECT USER_ID, USER_TYPE, IS_LOCKED, USER_STATUS, IS_MOBILE_APP, DEVICE_UUID
        INTO   l_user_id, l_user_type, l_is_locked, l_user_status, l_is_mob' || 'ile_app, l_stored_device_uuid
        FROM   APP_USERS_LOGIN
        WHERE  UPPER(USERNAME) = UPPER(l_username)
        AND    ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',                                  p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''اسم المستخدم أو كلمة المرور غير صحيحة'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid username or password'',           p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
    END;

    -- ===== 5. BUSINESS RULES =====
    IF l_is_locked = ''1'' THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                          p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''الحساب موقوف، تواصل مع الإدارة'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Account is locked'',      ' || '       p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 403;
        RETURN;
    END IF;

    IF l_user_status != ''1'' THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                            p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''الحساب غير نشط، تواصل مع الإدارة'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Account is inactive'',             p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 403;
        RETURN;
    END IF;

    IF NVL(l_is_mobile_app, ''0'') != ''1'' THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                                    p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''هذا الحساب غير مفعّل على تطبيق الموبايل'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Mobile access not enabled for this account'', p_write_null => TRUE);
        APEX_JSON.close_object;
      ' || '  :status := 403;
        RETURN;
    END IF;

    -- ===== 6. VERIFY PASSWORD =====
    SELECT COUNT(*) INTO l_check
    FROM   APP_USERS_LOGIN
    WHERE  UPPER(USERNAME) = UPPER(l_username)
    AND    PASSWORD = l_password;

    IF l_check = 0 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''اسم المستخدم أو كلمة المرور غير صحيحة'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Invalid username or password'',           p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 401;
        RETURN;
    END IF;

    -- ===== 6.5. DEVICE BINDING CHECK =====
    IF NVL(l_is_mobile_app, ''0'') = ''1'' THEN
        IF l_stored_device_uuid IS NULL THEN
            IF l_device_uuid IS NOT NULL THEN
                UPDATE SEC_USERS
                SET    DEVICE_UUID = l_device_uuid
                WHERE  ID = l_user_id;' || '
                COMMIT;
                l_stored_device_uuid := l_device_uuid;
            END IF;
        ELSIF l_device_uuid IS NULL OR l_stored_device_uuid != l_device_uuid THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',                                                        p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''هذا الحساب مرتبط بهاتف آخر. لا يمكنك تسجيل الدخول إلا من جهازك المعتمد.'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''This account is locked to another mobile device.'',                p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 403;
            RETURN;
        END IF;
    END IF;

    -- ===== 7. GENERATE TOKEN =====
    l_token := APEX_JWT.ENCODE(
        p_iss           => ''ORDS'',
        p_sub           => TO_CHAR(l_user_id),
        p_aud           => l_user_type,
        p_iat_ts        => SYSDATE,
        p_signature_key ' || '=> SYS.UTL_RAW.CAST_TO_RAW(''secretKey'')
    );

    -- ===== 8. FETCH FULL USER DATA =====
    SELECT * INTO l_rec
    FROM   APP_USERS_LOGIN
    WHERE  USER_ID = l_user_id
    AND    ROWNUM  = 1;

    -- ===== 9. SUCCESS RESPONSE =====
    :status := 200;
    APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''success'',             p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''تم تسجيل الدخول بنجاح'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Login successful'',   p_write_null => TRUE);
        APEX_JSON.write(''token'',     l_token,              p_write_null => TRUE);
        APEX_JSON.write(''isChangePassword'', NVL(l_rec.IS_CHANGE_PASSWORD, 0), p_write_null => TRUE);

        APEX_JSON.open_object(''user'');
            APEX_JSON.write(''userId'',           l_rec.USER_ID,            p_write_null => TRUE);
            APEX_JSON.write(''username'',         l_rec.USERNAME,           p_write_null => TRUE);
            APEX_JSON.write(' || '''userNameEn'',       l_rec.USER_NAME_EN,       p_write_null => TRUE);
            APEX_JSON.write(''userNameAr'',       l_rec.USER_NAME_AR,       p_write_null => TRUE);
            APEX_JSON.write(''email'',            l_rec.EMAIL,              p_write_null => TRUE);
            APEX_JSON.write(''phone'',            l_rec.PHONE,              p_write_null => TRUE);
            APEX_JSON.write(''userType'',         l_rec.USER_TYPE,          p_write_null => TRUE);
            APEX_JSON.write(''defaultCompanyId'', l_rec.DEFAULT_COMPANY_ID, p_write_null => TRUE);
            APEX_JSON.write(''defaultBranchId'',  l_rec.DEFAULT_BRANCH_ID,  p_write_null => TRUE);
            APEX_JSON.write(''companyName'',      l_rec.COMPANY_NAME,       p_write_null => TRUE);
            APEX_JSON.write(''branchName'',       l_rec.BRANCH_NAME,        p_write_null => TRUE);
            APEX_JSON.write(''isChangePassword'', NVL(l_rec.IS_CHANGE_PASSWORD, 0), p_write_null => TRUE);
            
            -- الحقول الجد' || 'يدة للتحكم بالخدمات المتاحة للمستخدم
            APEX_JSON.write(''allowAttendance'',  NVL(l_rec.ALLOW_ATTENDANCE, ''Y''), p_write_null => TRUE);
            APEX_JSON.write(''allowDailies'',     NVL(l_rec.ALLOW_DAILIES, ''Y''),    p_write_null => TRUE);

            APEX_JSON.open_object(''employee'');
                APEX_JSON.write(''employeeId'',   l_rec.EMPLOYEE_ID,        p_write_null => TRUE);
                APEX_JSON.write(''employeeCode'', l_rec.EMPLOYEE_CODE,      p_write_null => TRUE);
                APEX_JSON.write(''nameAr'',       l_rec.EMPLOYEE_NAME_AR,   p_write_null => TRUE);
                APEX_JSON.write(''nameEn'',       l_rec.EMPLOYEE_NAME_EN,   p_write_null => TRUE);
