    -- ===== 2. GET SITE_ID FROM QUERY PARAMS =====
    l_site_id := TO_NUMBER(:site_id);

    IF l_site_id IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',               p_write_null => TRUE);
