    -- ===== 3. GET TOTAL COUNT =====
    SELECT COUNT(*) INTO l_to' || 'tal
    FROM   HR_SITE_LOCATIONS
    WHERE  SITE_ID = l_site_id
    AND    STATUS  = ''1'';

    -- ===== 4. SUCCESS RESPONSE =====
    :status := 200;
    APEX_JSON.open_object;
