        APEX_JSON.write(''siteId'',    l_site_id,                    p_write_null => TRUE);
        APEX_JSON.write(''total'',     l_total,                      p_write_null => TRUE);

        APEX_JSON.open_array(''locations'');

        FOR rec IN (
            SELECT
                ID,
                NAME,
