                LATITUDE,
                LONGITUDE,
                ZONE_TYPE,
                ZONE_RADIUS,
                ZONE_LAT_NORTH,
                ZONE_LNG_EAST,
            ' || '    ZONE_LAT_SOUTH,
                ZONE_LNG_WEST,
                NOTES
            FROM HR_SITE_LOCATIONS
