                APEX_JSON.open_object(''zoneBounds'');
                    APEX_JSON.write(''latNorth'', rec.ZONE_LAT_NORTH, p_write_null => TRUE);
                    APEX_JSON.write(''lngEast'',  rec.ZONE_LNG_EAST,  p_write_null => TRUE);
                    APEX_JSON.write(''latSouth'', rec.ZONE_LAT_SOUTH, p_write_null => TRUE);
                    APEX_JSON.write(''lngWest'',  rec.ZONE_LNG_WEST,  p_write_null => TRUE);
                APEX_JSON.close_object;

                APEX_JSON.write(''notes'',        rec.NOTES,          p_write_null => TRUE);
