  ORDS.DEFINE_HANDLER(
      p_module_name    => 'Users',
      p_pattern        => 'ChangePassword',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'DECLARE
    l_header_value    VARCHAR2(4000);
    l_bearer_token    VARCHAR2(4000);
    l_token           APEX_JWT.T_TOKEN;
    l_user_object     APEX_JSON.T_VALUES;
    l_user_id         NUMBER;

    l_body            CLOB;
    l_body_values     APEX_JSON.T_VALUES;

    l_old_password    VARCHAR2(200);
    l_new_password    VARCHAR2(200);
    l_db_password     VARCHAR2(200);

BEGIN
    -- ===== 1. TOKEN VALIDATION =====
    l_header_value := OWA_UTIL.get_cgi_env(''Authorization'');

    IF l_header_value IS NULL OR INSTR(l_header_value, ''Bearer '') != 1 THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                  p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''يرجى تسجيل الدخول أولاً'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Authentication required'', p_write_null => TRUE);
        APEX_JSON.write(''errorCode'', ''TOKEN_REQUIRED'',         p_write_null => TRUE);
        APEX_JSON.close_object;
   ' || '     :status := 401;
        RETURN;
    END IF;

    l_bearer_token := SUBSTR(l_header_value, 8);

    BEGIN
        l_token := APEX_JWT.DECODE(
            p_value         => l_bearer_token,
            p_signature_key => SYS.UTL_RAW.CAST_TO_RAW(''secretKey'')
        );
        APEX_JSON.PARSE(l_user_object, l_token.payload);
        l_user_id := TO_NUMBER(APEX_JSON.GET_VARCHAR2(p_path => ''sub'', p_values => l_user_object));
    EXCEPTION
        WHEN OTHERS THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',          p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''Token غير صالح'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''Invalid token'',  p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 401;
            RETURN;
    END;

    -- ===== 2. READ BODY =====
    l_body := :body_text;

    IF l_body IS NULL THEN
        APEX_JSON.open_object;
        APE' || 'X_JSON.write(''status'',    ''error'',                      p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''لم نتمكن من قراءة البيانات'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Request body is empty'',      p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    APEX_JSON.PARSE(l_body_values, l_body);

    -- ===== 3. EXTRACT PARAMS =====
    l_old_password := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''oldPassword'', p_values => l_body_values));
    l_new_password := TRIM(APEX_JSON.GET_VARCHAR2(p_path => ''newPassword'', p_values => l_body_values));

    -- ===== 4. VALIDATE REQUIRED =====
    IF l_old_password IS NULL OR l_new_password IS NULL THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                               p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''كلمة المرور القديمة والجديدة مطلوبة'', p_write_null => TRUE);
        APEX_JSO' || 'N.write(''messageEn'', ''Old and new passwords are required'',  p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    -- ===== 5. VERIFY OLD PASSWORD =====
    BEGIN
        SELECT PASSWORD INTO l_db_password
        FROM   SEC_USERS
        WHERE  ID = l_user_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            APEX_JSON.open_object;
            APEX_JSON.write(''status'',    ''error'',                     p_write_null => TRUE);
            APEX_JSON.write(''messageAr'', ''المستخدم غير موجود بالجروب'', p_write_null => TRUE);
            APEX_JSON.write(''messageEn'', ''User not found'',            p_write_null => TRUE);
            APEX_JSON.close_object;
            :status := 404;
            RETURN;
    END;

    IF l_db_password != l_old_password THEN
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                         p_write_null => TRUE);
        APEX_JSON.write(''messageA' || 'r'', ''كلمة المرور القديمة غير صحيحة'', p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Invalid old password'',          p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 400;
        RETURN;
    END IF;

    -- ===== 6. UPDATE PASSWORD & FLAGS =====
    UPDATE SEC_USERS
    SET    PASSWORD             = l_new_password,
           IS_CHANGE_PASSWORD   = 0,            -- فك إجبارية التغيير
           IS_PASSWORD_CHANGED  = 1,            -- تم التغيير بنجاح
           PASSWORD_CHANGE_DATE = SYSDATE       -- تاريخ ووقت التغيير الحالي بالسيرفر
    WHERE  ID = l_user_id;

    COMMIT;

    -- ===== 7. SUCCESS RESPONSE =====
    :status := 200;
    APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''success'',                      p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''تم تغيير كلمة المرور بنجاح'',   p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''Password changed successfully'', p_write_null => TR' || 'UE);
    APEX_JSON.close_object;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        APEX_JSON.open_object;
        APEX_JSON.write(''status'',    ''error'',                      p_write_null => TRUE);
        APEX_JSON.write(''messageAr'', ''حدث خطأ غير متوقع بالخادم'',   p_write_null => TRUE);
        APEX_JSON.write(''messageEn'', ''An unexpected error occurred'', p_write_null => TRUE);
        APEX_JSON.close_object;
        :status := 500;
END;
');

